import java.util.Scanner;
class NeonNumGen
 {
   int m;
   int n;
   NeonNumGen()
   {
     m = 1;
     n = 100;
   }
   void accept()
   {
     Scanner sc = new Scanner(System.in);
     System.out.print("Enter start of range (m): ");
     m = sc.nextInt();
     System.out.print("Enter end of range (n): ");
     n = sc.nextInt();
   }
   int sum_digits(int num)
   {
     int sum = 0;
     while (num > 0)
     {
       sum += num  % 10;
       num /= 10;
     }
     return sum;
   }
   void generate()
   {
     System.out.println("Neon numbers between " + m + " and " + n + " are:");
     for (int i = m; i <= n; i++)
      {
       int square = i * i;
       int sum = sum_digits(square);
       if (sum == i)
            System.out.println(i);
      }
   }
   public static void main(String[] args)
   {
     NeonNumGen   obj = new NeonNumGen();
     obj.accept();
     obj.generate();
   }
}

import java.util.Scanner;
class StrFrequency
{
  String str;
  int len;
  StrFrequency()
  {
     str = "";
     len = 0;
    }
  void input()
  {
     Scanner sc = new Scanner(System.in);
     System.out.print("Enter a string: ");
     str = sc.nextLine();
     len = str.length();
   }
  void freq_Char()
   {
     String s = str.toLowerCase();
     boolean visited[] = new boolean[len];
     for (int i = 0; i < len; i++)
     {
       if (visited[i] == true)
         continue;
       int count = 1;
       for (int j = i + 1; j < len; j++)
       {
         if (s.charAt(i) == s.charAt(j))
         {
           count++;
           visited[j] = true;
          }
       }
       System.out.println(s.charAt(i) + " = " + count);
      }
    }
  void display()
   {
     System.out.println("\nEntered String: " + str);
     System.out.println("Character Frequencies:");
     freq_Char();
   }
  public static void main(String[] args)
  {
     StrFrequency obj = new StrFrequency();
     obj.input();
     obj.display();
  }
}

import java.util.Scanner;
class Diagsum
 {
   int arr[][];
   int n;
   Diagsum(int nn)
   {
     n = nn;
     arr = new int[n][n];
   }
   void accept()
   {
     Scanner sc = new Scanner(System.in);
     System.out.println("Enter elements of the matrix:");
     for (int i = 0; i < n; i++)
      {
       for (int j = 0; j < n; j++)
            arr[i][j] = sc.nextInt();
       }
    }
   void diagonal_sum()
   {
     int sum = 0;
     for (int i = 0; i < n; i++)
          sum += arr[i][i];
     System.out.println("Sum of principal diagonal = " + sum);
   }
   void display()
   {
     System.out.println("Matrix is:");
     for (int i = 0; i < n; i++)
     {
       for (int j = 0; j < n; j++)
            System.out.print(arr[i][j] + "\t");
       System.out.println();
     }
     diagonal_sum();
    }
   public static void main(String[] args)
   {
     Scanner sc = new Scanner(System.in);
     System.out.print("Enter order of matrix: ");
     int n = sc.nextInt();
     Diagsum obj = new Diagsum(n);
     obj.accept();
     obj.display();
   }
}

import java.io.*;
import java.util.*;
class FileSort
{ int file[];
  int m;
  FileSort(int mm)
  {
     m = mm;
     file = new int[m];
   }
  void readFile()
   {
       File f = new File("Number.txt");
       Scanner sc = new Scanner(f);
       int i = 0;
       while (sc.hasNextInt() && i < m)
       {
         file[i] = sc.nextInt();
         i++;
        }
       sc.close();
    }
   void sort()
    {
     for (int i = 0; i < m - 1; i++)
      {
       for (int j = 0; j < m - i - 1; j++)
       {
         if (file[j] > file[j + 1])
         { int temp = file[j];
           file[j] = file[j + 1];
           file[j + 1] = temp;
          }
        }
      }
    }
  void show()
  {
     System.out.println("Numbers in ascending order:");
     for (int i = 0; i < m; i++)
       System.out.print(file[i] + " ");
   }
  public static void main(String[] args)
  {
     FileSort obj = new FileSort(50);
     obj.readFile();
     obj.sort();
     obj.show();
  }
}

